NUMERIC=[]
def verify(name,a,b):
 assert math.isclose(a,b,rel_tol=1e-9,abs_tol=1e-9),(name,a,b)
 NUMERIC.append(name)
def triangle(ab,bc,ca,names='ABC'):
 assert min(ab+bc-ca,bc+ca-ab,ca+ab-bc)>0
 x=(ab*ab+ca*ca-bc*bc)/(2*ca)
 return dict(zip(names,[[0,0],[x,math.sqrt(ab*ab-x*x)],[ca,0]]))
def angle(p,a,o,b):
 u=subv(p[a],p[o]);v=subv(p[b],p[o]);return math.degrees(math.acos(max(-1,min(1,sum(u[i]*v[i] for i in (0,1))/(dist(p[a],p[o])*dist(p[b],p[o]))))))
def area(p,ns):return abs(sum(p[ns[i]][0]*p[ns[(i+1)%len(ns)]][1]-p[ns[(i+1)%len(ns)]][0]*p[ns[i]][1] for i in range(len(ns))))/2
def pair(p,k,names=('A1','B1','C1')):
 """Two exact similar triangles separated vertically, in a common scale."""
 h=max(v[1] for v in p.values())-min(v[1] for v in p.values());off=[0,-k*h-3]
 q={names[i]:addv([k*x for x in p[n]],off) for i,n in enumerate('ABC')};q.update(p)
 labels=dict(zip(names,['A₁','B₁','C₁'])) if names==('A1','B1','C1') else {}
 v=sc(list('ABC')+list(names),tri()+tri(list(names)))
 checks=[ratio('A','B',names[0],names[1],1/k),ratio('B','C',names[1],names[2],1/k),ratio('C','A',names[2],names[0],1/k)]
 return q,v,checks,labels
def bisector(ab,bc,ca,vertex='A'):
 p=triangle(ab,bc,ca)
 if vertex=='A':p['D']=mix(p['B'],p['C'],ab/(ab+ca));checks=[col('B','D','C'),ratio('B','D','D','C',ab/ca)]
 else:p['D']=mix(p['A'],p['C'],ab/(ab+bc));checks=[col('A','D','C'),ratio('A','D','D','C',ab/bc)]
 a,b=('B','C') if vertex=='A' else ('A','C');checks += [ang(a,vertex,'D',angle(p,a,vertex,b)/2),ang('D',vertex,b,angle(p,a,vertex,b)/2)]
 return p,sc('ABCD',tri()+[[vertex,'D']],angleArcs=[arc(vertex,a,'D',1),arc(vertex,'D',b,1)]),checks
